//! Lawyer cron-schedule reference page as a Dioxus component (#956 Phase 4).
//!
//! The successor to the `views::pages::admin::schedules`. Lists the
//! Kubernetes `CronJob`s that drive Neon Law Navigator's scheduled work with
//! their cron expression, a human cadence, what each does, and — where the job
//! can be started on demand — a "Run now" trigger.
//!
//! This is a *declared* reference, not a live cluster read (`web` has no
//! Kubernetes API access). What it declares is the deployment render:
//! [`RENDERED_CRON_JOBS`] is generated by `webapp/build.rs` from the
//! `resources:` list in `examples/deploy/k8s/exports/kustomization.yaml` — the
//! same list `kubectl kustomize` resolves when `ops ship` reconciles the
//! cluster. A job appears here because it ships, not because someone remembered
//! to add a row.
//!
//! Only the operator-facing prose is written by hand, in [`JOB_COPY`], keyed by
//! the `CronJob`'s `metadata.name`. A rendered job with no entry there still
//! gets a row carrying its real name and schedule, so the page can never be
//! shorter than the render; the missing prose is a test failure rather than an
//! omission the reader has to notice.
//!
//! `POST /app/admin/schedules/{job}/run` stays on the `portal::cron_schedules`
//! handler and already follows post/redirect/get: it redirects back here with
//! `?notice=queued:{slug}` (or `not_queued`), which renders as a toast.

use dioxus::prelude::*;
use serde::{Deserialize, Serialize};

use crate::components::{Column, DataTable, SortState, Toast, ToastTone};
use crate::people::ViewerRole;

/// The page's own path, and the base the "Run now" forms post under.
pub const SCHEDULES_PATH: &str = "/app/admin/schedules";

/// One `CronJob` the deployment render ships.
///
/// `webapp/build.rs` reads these out of the manifests named by
/// `examples/deploy/k8s/exports/kustomization.yaml`'s `resources:` list, so the
/// set is whatever `ops ship` applies.
pub struct RenderedCronJob {
    /// The `CronJob`'s `metadata.name`.
    pub name: &'static str,
    /// `spec.schedule` — the cron expression (UTC), exactly as deployed.
    pub schedule: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/rendered_cron_jobs.rs"));

/// Operator-facing prose for one shipped `CronJob`, keyed by its
/// `metadata.name`.
///
/// A manifest carries no display name, no Pacific cadence, and no account of
/// what the job is for, so that copy is written here. What this table
/// deliberately does *not* carry is the cron expression or the job's presence:
/// both come from the render, which is why it cannot put a job on the page that
/// no cluster runs.
struct JobCopy {
    /// The `CronJob`'s `metadata.name`, joining this copy to the render.
    cron_name: &'static str,
    /// Display name.
    name: &'static str,
    /// Human cadence, in the workspace's Pacific convention.
    cadence: &'static str,
    /// What the job does.
    description: &'static str,
    /// The `POST` route segment that queues this job on demand, for the jobs
    /// `portal::cron_schedules` can start. `None` where there is no such route:
    /// a self-contained batch has no durable workflow for the Restate ingress
    /// to invoke, and a button that answers 404 is worse than no button.
    manual_slug: Option<&'static str>,
}

